import {canonical,normalizeTrade,summarize} from './core.mjs';
const $=id=>document.getElementById(id),API='https://api.geckoterminal.com/api/v2';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const compact=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(n);
const short=s=>s.length>18?s.slice(0,7)+'…'+s.slice(-6):s;
const state={token:{address:'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263',network:'solana',symbol:'BONK',name:'Bonk'},minutes:60,trades:[],pools:[],fetched:0,busy:false,generation:0,searchGeneration:0,searchBusy:false};
const cache=new Map();
function error(message){$('error').textContent=message;$('error').hidden=!message}
function safeUrl(network,address,type='tokens'){return `https://www.geckoterminal.com/${encodeURIComponent(network)}/${type}/${encodeURIComponent(address)}`}
async function api(path,force=false){const old=cache.get(path);if(!force&&old&&Date.now()-old.time<45000)return old.value;const response=await fetch(API+path,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error(response.status===429?'The data provider is rate-limiting requests. Wait a minute, then refresh.':`The data provider could not return swaps (HTTP ${response.status}). Please try again.`);const value=await response.json();if(!Array.isArray(value.data))throw new Error('The data provider returned an unexpected response. Please try again.');cache.set(path,{time:Date.now(),value});return value}
function tokenFromIncluded(t){const a=t.attributes||{};if(!a.address)return null;return {address:a.address,network:t.id.slice(0,-a.address.length-1),symbol:a.symbol||a.name||'Token',name:a.name||a.symbol||'Token'}}
async function search(query){
  query=query.trim();if(query.length<2||query.length>160)throw new Error('Enter at least 2 characters of a ticker or contract address.');
  const generation=++state.searchGeneration;state.searchBusy=true;$('search-button').disabled=true;$('search-status').textContent='Finding matching tokens…';$('results').hidden=true;error('');
  try{const j=await api(`/search/pools?query=${encodeURIComponent(query)}&include=base_token,quote_token`);if(generation!==state.searchGeneration)return [];
    const tokens=(j.included||[]).filter(t=>t.type==='token').map(tokenFromIncluded).filter(Boolean);const q=query.toLowerCase();
    const found=tokens.filter(t=>canonical(t.address)===canonical(query)||t.symbol.toLowerCase().includes(q)||t.name.toLowerCase().includes(q)).map(t=>({...t,liquidity:j.data.filter(p=>[p.relationships?.base_token?.data?.id,p.relationships?.quote_token?.data?.id].includes(`${t.network}_${t.address}`)).reduce((s,p)=>s+(Number(p.attributes.reserve_in_usd)||0),0)})).sort((a,b)=>Number(b.symbol.toLowerCase()===q)-Number(a.symbol.toLowerCase()===q)||b.liquidity-a.liquidity).slice(0,12);
    $('results').replaceChildren();for(const token of found){const button=document.createElement('button');button.type='button';button.className='result';const main=document.createElement('strong');main.textContent=`${token.symbol} · ${token.name}`;const meta=document.createElement('small');meta.className='result-meta';meta.textContent=`${token.network} · ${compact(token.liquidity)} indexed liquidity`;const address=document.createElement('small');address.textContent=token.address;button.append(main,meta,address);button.addEventListener('click',()=>selectToken(token));$('results').append(button)}
    $('search-status').textContent=found.length?`${found.length} matches · choose the correct chain and contract.`:'No indexed match found. Try the exact contract address; some new tokens may not be covered yet.';$('results').hidden=!found.length;return found.map(({symbol,name,network,address})=>({symbol,name,network,address}));
  }catch(e){if(generation===state.searchGeneration){$('search-status').textContent='Search unavailable.';error(e.message)}throw e}finally{if(generation===state.searchGeneration){state.searchBusy=false;$('search-button').disabled=false}}
}
function updateIdentity(){const t=state.token;$('symbol').textContent=t.symbol;$('network').textContent=t.network;$('token-name').textContent=t.name;$('address').textContent=t.address;$('avatar').textContent=t.symbol.slice(0,1).toUpperCase();$('token-link').href=safeUrl(t.network,t.address);document.title=`${t.symbol} Flow · Meme Fast`}
async function selectToken(token){state.generation++;state.token=token;state.trades=[];state.pools=[];state.fetched=0;$('results').hidden=true;$('search-status').textContent='';updateIdentity();render();return load()}
async function load(){
  const generation=++state.generation,token={...state.token};state.busy=true;$('refresh').disabled=true;$('charts').setAttribute('aria-busy','true');$('updated').textContent='Fetching swaps…';error('');
  try{const j=await api(`/networks/${encodeURIComponent(token.network)}/tokens/${encodeURIComponent(token.address)}/pools?include=base_token,quote_token`);
    const pools=j.data.filter(p=>{const ids=[p.relationships?.base_token?.data?.id,p.relationships?.quote_token?.data?.id];return ids.some(id=>canonical(id?.slice(token.network.length+1))===canonical(token.address))}).sort((a,b)=>(Number(b.attributes.reserve_in_usd)||0)-(Number(a.attributes.reserve_in_usd)||0)).slice(0,3).map(p=>({address:p.attributes.address,name:p.attributes.name,dex:p.relationships?.dex?.data?.id||'',count:0,failed:false}));
    if(!pools.length)throw new Error('No indexed pools found for this token. Try another token or contract address.');
    const batches=await Promise.allSettled(pools.map(p=>api(`/networks/${encodeURIComponent(token.network)}/pools/${encodeURIComponent(p.address)}/trades`)));
    if(generation!==state.generation)return;
    const trades=[];let failures=0,skipped=0;for(let i=0;i<batches.length;i++){const result=batches[i],p=pools[i];if(result.status==='rejected'){p.failed=true;failures++;continue}p.count=result.value.data.length;for(const event of result.value.data){const trade=normalizeTrade(event,token.address,p);if(trade)trades.push(trade);else skipped++}}
    if(failures===pools.length)throw batches.find(b=>b.status==='rejected').reason;
    state.trades=trades;state.pools=pools;state.skipped=skipped;state.fetched=Date.now();render();if(failures)error(`${failures} pool request${failures>1?'s':''} failed. The chart includes only successful pools.`);
    return currentSummary();
  }catch(e){if(generation===state.generation){error(e.message);$('updated').textContent=state.fetched?'Refresh failed · previous snapshot':'Data unavailable';if(!state.fetched){$('coverage-text').textContent='No swaps could be loaded. Refresh to try again.';$('tape').replaceChildren(emptyRow('Data unavailable.'))}}return null}
  finally{if(generation===state.generation){state.busy=false;$('refresh').disabled=false;$('charts').setAttribute('aria-busy','false')}}
}
function emptyRow(text){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.className='table-empty';td.textContent=text;tr.append(td);return tr}
function currentSummary(){const s=summarize(state.trades,state.minutes,state.fetched||Date.now());return {token:state.token,windowMinutes:state.minutes,buyUSD:s.buy,sellUSD:s.sell,netUSD:s.net,swapCount:s.rows.length,coverage:'Recent swap sample, up to 300 swaps per pool from up to 3 pools',updatedAt:state.fetched?new Date(state.fetched).toISOString():null}}
function render(){
  const s=summarize(state.trades,state.minutes,state.fetched||Date.now()),loaded=state.fetched>0;
  document.querySelectorAll('[data-window]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.window)===state.minutes)));
  $('net-label').textContent=s.net<0?'Net outflow':s.net>0?'Net inflow':'Net flow';$('net-value').textContent=loaded?(Math.abs(s.net)>=100000?compact(Math.abs(s.net)):money(Math.abs(s.net))):'—';$('net-value').title=loaded?money(Math.abs(s.net)):'';$('swap-count').textContent=loaded?`${s.rows.length.toLocaleString()} observed swaps`:'Fetching actual swaps';
  $('buy-value').textContent=loaded?money(s.buy):'—';$('sell-value').textContent=loaded?money(s.sell):'—';
  for(const side of ['buy','sell'])$(''+side+'-share').textContent=loaded?`${s[side+'Count'].toLocaleString()} swaps · ${s.total?(s[side]/s.total*100).toFixed(1):'0.0'}%`:'—';
  $('buy-ring').setAttribute('stroke-dasharray',`${s.total?s.buy/s.total*100:0} ${s.total?100-s.buy/s.total*100:100}`);$('sell-ring').style.opacity=s.total?'1':'0';$('donut').setAttribute('aria-label',loaded?`Observed buys ${money(s.buy)}, sells ${money(s.sell)}, net ${money(s.net)}.`:'Waiting for swap data');
  const max=Math.max(...s.bands.flatMap(b=>[b.buy,b.sell]),1);$('size-bars').replaceChildren();
  for(const band of s.bands){const row=document.createElement('div');row.className='size-row';for(const side of ['buy','label','sell']){const el=document.createElement('div');if(side==='label'){el.className='size-label';el.textContent=band.name;const small=document.createElement('small');small.textContent=band.label;el.append(small)}else{el.className='size-side';el.textContent=loaded?money(band[side]):'—';const track=document.createElement('div'),fill=document.createElement('div');track.className='bar-track';fill.className=`bar-fill ${side}`;fill.style.width=`${100*band[side]/max}%`;track.append(fill);el.append(track)}row.append(el)}$('size-bars').append(row)}
  $('tape').replaceChildren();for(const trade of s.rows.slice(0,10)){const tr=document.createElement('tr');const time=document.createElement('td');time.textContent=new Date(trade.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});time.title=new Date(trade.time).toLocaleString();const side=document.createElement('td'),badge=document.createElement('span');badge.className=`side-badge ${trade.side}`;badge.textContent=trade.side==='buy'?'Buy':'Sell';side.append(badge);const amount=document.createElement('td');amount.className='numeric';amount.textContent=money(trade.usd);const pool=document.createElement('td');pool.textContent=trade.pool;const transaction=document.createElement('td');transaction.className='transaction';transaction.textContent=short(trade.hash)||'—';transaction.title=trade.hash;tr.append(time,side,amount,pool,transaction);$('tape').append(tr)}
  if(!s.rows.length)$('tape').append(emptyRow(loaded?'No observed swaps in this window. Try a longer window.':'Loading swaps…'));
  $('tape-count').textContent=loaded?`${Math.min(10,s.rows.length)} OF ${s.rows.length} SWAPS`:'—';
  if(loaded){const ok=state.pools.filter(p=>!p.failed).length,capped=state.pools.filter(p=>p.count>=300).length;const span=s.rows.length?` Observed ${new Date(s.rows[s.rows.length-1].time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}–${new Date(s.rows[0].time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}.`:'';$('coverage-text').textContent=`${ok} of ${state.pools.length} selected pools · up to 300 recent swaps per pool.${span} ${capped?`${capped} pool${capped>1?'s':''} reached the 300-swap limit. `:''}Totals cover the returned sample, not the whole market.${state.skipped?` ${state.skipped} unclassifiable records excluded.`:''}`;$('updated').textContent=`Updated ${new Date(state.fetched).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`}
  else{$('coverage-text').textContent='Loading the most liquid indexed pools for this token.';$('updated').textContent='Loading swaps…'}
  $('pool-list').replaceChildren();for(const pool of state.pools){const a=document.createElement('a');a.href=safeUrl(state.token.network,pool.address,'pools');a.target='_blank';a.rel='noopener noreferrer';a.textContent=`${pool.name} · ${pool.dex}${pool.failed?' · unavailable':''} ↗`;$('pool-list').append(a)}
}
$('search-form').addEventListener('submit',e=>{e.preventDefault();search($('query').value).catch(e=>error(e.message))});$('refresh').addEventListener('click',()=>load());document.querySelectorAll('[data-window]').forEach(b=>b.addEventListener('click',()=>{state.minutes=Number(b.dataset.window);render()}));
setInterval(()=>{if(!document.hidden&&!state.busy&&!state.searchBusy)load()},60000);
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [
  {name:'search_tokens',description:'Find indexed token matches and show them for selection.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:2,maxLength:160}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(typeof input?.query!=='string'||input.query.trim().length<2||input.query.length>160)throw new Error('Enter a ticker or contract address between 2 and 160 characters.');$('query').value=input.query;return search(input.query)}},
  {name:'read_observed_flow',description:'Read the currently displayed token swap sample and coverage.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>currentSummary()}
]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}}
updateIdentity();render();load();
